#!/usr/bin/env node
/**
 * Seed Firestore with real-world assets for monitoring.
 * Bridges: from FHWA NBI public data (real coordinates, real ratings).
 * Farmland: from USDA CDL regions (real agricultural areas).
 *
 * This script ONLY registers asset locations and metadata.
 * All degradation history, risk scores, and alerts will be
 * generated by the live pipeline (imagery → agents → Firestore).
 *
 * Run: GCP_PROJECT=your-project node infrastructure/seed-assets.js
 */

import { initializeApp } from "firebase-admin/app";
import { getFirestore } from "firebase-admin/firestore";

initializeApp({ projectId: process.env.GCP_PROJECT });
