async function seed() {
  const ALL_ASSETS = [...BRIDGES, ...FARMLAND];
  let seeded = 0;

  for (const asset of ALL_ASSETS) {
    const doc = {
      ...asset,
      monitoring: {
        active: true,
        frequencyDays: 5,
        alertThreshold: 60,
        notifyEmails: [],
      },
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    await db.collection("assets").doc(asset.id).set(doc);
    seeded++;
    console.log(`✓ Registered ${asset.id} (${asset.type})`);
  }

  console.log(`\n✅ Registered ${seeded} assets in Firestore.`);
  console.log("   The pipeline will generate all analysis data from live satellite imagery.");
}

seed().catch(console.error);
